import { createWalletController, shortAddress, assertSettlementTransaction, assertAuthenticationChallenge } from './wallet.js';
const currency=(value,precision=2)=>Number.isFinite(Number(value))&&value!==null?new Intl.NumberFormat('en-US',{minimumFractionDigits:precision,maximumFractionDigits:precision}).format(Number(value)):'—';
const discount=()=>0;

const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset = file => `../assets/${file}`;
const brands={SOL:'sol.svg',USDC:'usdc.png',BONK:'bonk.png',WIF:'wif.png',JUP:'jup.svg',Raydium:'raydium.svg',Orca:'orca.png',Meteora:'meteora.svg',Phantom:'phantom.svg',Solflare:'solflare.svg',Backpack:'backpack.png'};
const brandLogo=(name,cls='asset-logo')=>brands[name]?`<img class="${cls}" src="${asset('brands/'+brands[name])}" alt="" aria-hidden="true" data-brand="${esc(name.toLowerCase())}" loading="eager" decoding="async">`:`<span class="${cls}" aria-hidden="true">${esc(String(name||'').slice(0,1))}</span>`;

const icons = {
 market:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 wallet:'<path d="M20 8V6a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h15V8H5a2 2 0 0 1 0-4"/><path d="M20 12h-5v4h5"/>',
 list:'<path d="M9 5h12M9 12h12M9 19h12M3 5h1M3 12h1M3 19h1"/>',
 bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',
 activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
 up:'<path d="M6 18 18 6M6 6h12v12"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
 filter:'<path d="M3 6h6m4 0h8M3 12h12m4 0h2M3 18h3m4 0h11"/><circle cx="11" cy="6" r="2"/><circle cx="17" cy="12" r="2"/><circle cx="8" cy="18" r="2"/>',
 lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',
 help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3c-1 .5-1 1-1 2m0 3h.01"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',
 shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',
 globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',
 menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
 logout:'<path d="M9 4H4v16h5m5-4 4-4-4-4m-6 4h13"/>',
 refresh:'<path d="M20 6v5h-5M4 18v-5h5"/><path d="M5 8a8 8 0 0 1 14-2m0 10A8 8 0 0 1 5 2" transform="translate(0 0)"/>',
};
const referenceLabel=p=>p.verifiedSlot?`Verified at slot ${esc(p.verifiedSlot)}`:'Raydium Fee Key';
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.market}</svg>`;
function mountIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el => {el.innerHTML=icon(el.dataset.icon);el.removeAttribute('data-icon');});}
const KEY='sona-watchlist-v1';
const emptyScan=()=>({truncated:false,scannedCandidates:null,totalCandidates:null,rejected:0});
const fresh = () => ({connected:false,address:null,balance:null,listings:[],positions:[],saved:[],offers:[],activity:[],loading:true,error:null,inventoryError:null,inventoryLoading:false,inventoryScan:emptyScan(),config:null});
function focusToken(root){const el=document.activeElement;if(!root?.contains(el))return null;return {id:el.id,data:{...el.dataset},tag:el.tagName};}
function restoreFocus(token,root){if(!token)return;const el=token.id?root.querySelector(`[id="${CSS.escape(token.id)}"]`):[...root.querySelectorAll('[data-action]')].find(el=>el.tagName===token.tag&&Object.entries(token.data).every(([k,v])=>el.dataset[k]===v));if(el)el.focus({preventScroll:true});else{const heading=$('#result-count')?.closest('h2');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}}
let state=fresh();
try{const saved=JSON.parse(localStorage.getItem(KEY));if(Array.isArray(saved))state.saved=saved.filter(id=>typeof id==='string');}catch{}
const ui={page:'market',tab:'all',query:'',protocol:'all',lock:'all',sort:'newest',view:'list',filters:false,detailTab:'overview',listingTab:'active'};
let currentPosition=null,wizard=null,pendingAction=null,lastFocus=null,toastTimer,dismissTimer;
const motionAllowed=()=>!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
function animateElement(element,keyframes,options={}){if(motionAllowed()&&element?.animate)element.animate(keyframes,{duration:240,easing:'cubic-bezier(.22,1,.36,1)',...options});}
const pageNames={market:'Marketplace',portfolio:'My positions',listings:'My listings',saved:'Watchlist',activity:'Activity'};
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state.saved));}catch{}}
let sessionToken=null,sessionAddress=null,refreshing=false;
const reviewedTrades=new Map();
const wallet=createWalletController({onChange:account=>{
 const changed=state.address!==account.address;
 state.connected=account.connected;state.address=account.address;
 if(changed){sessionToken=null;sessionAddress=null;state.balance=null;state.positions=[];state.offers=[];state.activity=[];state.inventoryError=null;state.inventoryLoading=account.connected;state.inventoryScan=emptyScan();if(!account.connected)close();}
 render();
}});
function positionView(p){return {...p,id:p.id||p.mint,positionId:p.mint,owner:p.seller||p.owner||state.address,base:p.base||shortAddress(p.mintA||p.poolId||p.mint),quote:p.quote||'Fee Key',protocol:'Raydium',type:'Fee rights',lockDays:null,feeShare:100,referenceValue:null,fees30d:null,price:p.price??(p.priceLamports?Number(p.priceLamports)/1e9:null),age:Date.now()-Date.parse(p.createdAt||0)};}
async function api(path,{method='GET',body,authenticated=false}={}){
 if(authenticated)await ensureSession();
 const response=await fetch(path,{method,headers:{...(body?{'Content-Type':'application/json'}:{}),...(sessionToken?{Authorization:`Bearer ${sessionToken}`}:{})},...(body?{body:JSON.stringify(body)}:{}),cache:'no-store'});
 const result=await response.json().catch(()=>({error:'The service returned an unreadable response.'}));
 if(!response.ok){if(response.status===401){sessionToken=null;sessionAddress=null;}throw new Error(typeof result.error==='string'?result.error:result.error?.message||result.message||'The request could not be completed.');}
 return result;
}
async function ensureSession(){
 if(!state.connected||!wallet.address)throw new Error('Connect your wallet first.');
 if(sessionToken&&sessionAddress===wallet.address)return;
 const address=wallet.address;
 const challenge=await api('/api/auth/challenge',{method:'POST',body:{address}});
 if(wallet.address!==address)throw new Error('Your wallet changed. Connect again.');
 assertAuthenticationChallenge(challenge,{address,origin:location.origin,cluster:state.config?.cluster||'mainnet-beta'});
 const signatureBase64=await wallet.signMessage(challenge.message);
 if(wallet.address!==address)throw new Error('Your wallet changed. Connect again.');
 const result=await api('/api/auth/verify',{method:'POST',body:{address,challengeId:challenge.challengeId,signatureBase64}});
 if(wallet.address!==address)throw new Error('Your wallet changed. Connect again.');
 sessionToken=result.token;sessionAddress=address;
}
async function refreshData(){
 if(refreshing)return;refreshing=true;
 try{const [config,market]=await Promise.all([api('/api/config'),api('/api/listings')]);state.config=config;wallet.setChain(config.cluster);state.listings=market.listings.map(positionView);state.error=null;
  if(state.connected){const address=state.address;try{const account=await api(`/api/wallet/${encodeURIComponent(address)}`);if(state.address===address){state.balance=Number(account.balanceLamports)/1e9;state.positions=account.positions.map(positionView);state.inventoryScan={truncated:account.truncated===true,scannedCandidates:Number.isSafeInteger(account.scannedCandidates)?account.scannedCandidates:null,totalCandidates:Number.isSafeInteger(account.totalCandidates)?account.totalCandidates:null,rejected:Array.isArray(account.rejected)?account.rejected.length:0};state.listings=[...state.listings,...account.listings.filter(p=>!state.listings.some(l=>l.id===p.id)).map(positionView)];state.offers=account.trades||[];state.activity=account.activity||[];state.inventoryError=null;state.inventoryLoading=false;}}catch(error){if(state.address===address){state.balance=null;state.positions=[];state.offers=[];state.activity=[];state.inventoryError=error.message;state.inventoryLoading=false;state.inventoryScan=emptyScan();}}}
 }catch(error){state.error=error.message;}finally{state.loading=false;refreshing=false;render();}
}
const solDecimal=value=>{const amount=BigInt(value);return `${amount/1000000000n}.${(amount%1000000000n).toString().padStart(9,'0').replace(/0+$/,'')||'0'}`;};
const chainLabel=()=>state.config?.cluster==='devnet'?'Solana devnet':state.config?.cluster==='testnet'?'Solana testnet':'Solana mainnet';
const explorer=(kind,id)=>`https://explorer.solana.com/${kind}/${encodeURIComponent(id)}${state.config?.cluster&&state.config.cluster!=='mainnet-beta'?`?cluster=${encodeURIComponent(state.config.cluster)}`:''}`;
const lamportsToSol=value=>{if(value===null||value===undefined)return '—';const [whole,fraction]=solDecimal(value).split('.');return `${BigInt(whole).toLocaleString('en-US')}.${fraction.padEnd(2,'0')}`;};
function solToLamports(value){if(!/^(0|[1-9][0-9]*)(\.[0-9]{1,9})?$/.test(value))throw new Error('Enter a positive SOL amount with up to nine decimals.');const [whole,fraction='']=value.split('.');const amount=BigInt(whole)*1000000000n+BigInt(fraction.padEnd(9,'0'));if(amount<=0n||amount>1000000n*1000000000n)throw new Error('Enter a price above zero and no more than 1,000,000 SOL.');return amount.toString();}
async function runAction(button,action){if(button?.disabled)return;const wasDisabled=button?.disabled;if(button){button.disabled=true;button.setAttribute('aria-busy','true');}try{await action();}catch(error){toast(error.message||'The request could not be completed.');}finally{if(button?.isConnected){button.disabled=Boolean(wasDisabled);button.removeAttribute('aria-busy');}}}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function tag(p){return `<span class="type-tag ${p.type==='LP position'?'lp':''}">${esc(p.type)}</span>`;}
function lockText(p){return p.lockDays===null?'Permanent':`${p.lockDays} days`;}
function tokens(p){return `<span class="token-stack"><span class="token">${brandLogo(p.base)}</span><span class="token quote">${brandLogo(p.quote)}</span></span>`;}
function pair(p){return `<span class="pair">${tokens(p)}<span><span class="pair-name">${esc(p.base)} <span class="pair-divider">/</span> ${esc(p.quote)}</span><span class="pair-meta">${brandLogo(p.protocol,'protocol-logo')}${esc(p.protocol)}</span></span></span>`;}
function saveButton(p){return `<button class="icon-btn save-button ${state.saved.includes(p.id)?'saved':''}" data-action="save" data-id="${esc(p.id)}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${esc(p.base)} ${esc(p.quote)} ${esc(p.protocol)}" aria-pressed="${state.saved.includes(p.id)}">${icon('bookmark')}</button>`;}
const intro=(eyebrow,title,desc,action='')=>`<section class="page-intro"><div><h1>${title}</h1><p>${desc}</p></div>${action}</section>`;
const createButton=()=>`<button class="primary" data-action="create">${icon('plus')}List a position</button>`;
const empty=(title,desc,action='',symbol='search')=>`<div class="empty-state"><div class="empty-icon">${icon(symbol)}</div><h3>${title}</h3><p>${desc}</p>${action}</div>`;
function nav(){
 $('#main-nav').innerHTML=Object.entries(pageNames).map(([key,label])=>`<button class="nav-item ${ui.page===key?'active':''}" data-action="nav" data-page="${key}" ${ui.page===key?'aria-current="page"':''} title="${label}">${icon({market:'market',portfolio:'wallet',listings:'list',saved:'bookmark',activity:'activity'}[key])}<span class="nav-label">${label}</span>${key==='saved'&&state.saved.length?`<span class="nav-count">${state.saved.length}</span>`:''}</button>`).join('');
 $('#page-label').textContent=pageNames[ui.page];
 $('#wallet-button').innerHTML=icon('wallet')+`<span>${state.connected?shortAddress(state.address):'Connect wallet'}</span>`;
}
function render(){nav();if(ui.page==='market'||ui.page==='saved')renderMarket();else if(ui.page==='portfolio')renderPortfolio();else if(ui.page==='listings')renderListings();else renderActivity();mountIcons();}
function filtered(){let items=state.listings.filter(p=>p.status==='active'&&(p.visibility!=='private')&&(ui.page!=='saved'||state.saved.includes(p.id)));if(ui.tab!=='all')items=items.filter(p=>p.type===ui.tab);if(ui.query)items=items.filter(p=>`${p.base} ${p.quote} ${p.protocol}`.toLowerCase().includes(ui.query.toLowerCase()));if(ui.protocol!=='all')items=items.filter(p=>p.protocol===ui.protocol);if(ui.lock!=='all')items=items.filter(p=>ui.lock==='permanent'?p.lockDays===null:p.lockDays!==null&&p.lockDays<=90);return items.sort((a,b)=>ui.sort==='price-low'?a.price-b.price:ui.sort==='price-high'?b.price-a.price:ui.sort==='discount'?discount(b)-discount(a):a.age-b.age);}
function renderMarket(){
 const focused=focusToken($('#main'));
 const saved=ui.page==='saved';
 $('#main').innerHTML=`${saved?intro('Saved positions','Your watchlist','Positions you’re following, together in one place.'): `<section class="hero"><div class="hero-main"><div class="hero-copy"><span class="eyebrow hero-network">${brandLogo('SOL')}Built on Solana</span><h1>Locked liquidity.<br><em>Open possibilities.</em></h1><p>A market for Raydium Fee Keys.<br>Liquidity stays locked.</p></div></div><div class="hero-feature"><span class="eyebrow">Position essentials</span><h2>Know what<br>changes hands.</h2><p>Understand ownership, fee rights and the underlying lock.</p><img class="feature-art" src="${asset('WTuFQeqWgOcQVCks16yKxgDaefI.png')}" alt=""><button class="text-link" data-action="guide">How positions work ${icon('up')}</button></div></section>`}
 <div class="section-heading"><h2>${saved?'Your watchlist':'Explore positions'} <span class="count-badge" id="result-count"></span></h2>${createButton()}</div>
 <div class="toolbar"><div class="tabs" aria-label="Position type">${['all','Fee rights','LP position'].map(t=>`<button class="tab ${ui.tab===t?'active':''}" data-action="tab" data-tab="${t}" aria-pressed="${ui.tab===t}">${t==='all'?'All positions':t==='LP position'?'LP positions':'Fee rights'}</button>`).join('')}</div><div class="toolbar-right"><label class="search">${icon('search')}<input id="search" type="search" placeholder="Search token or protocol" aria-label="Search token or protocol" value="${esc(ui.query)}"></label><button class="secondary filter-btn" data-action="filters" aria-expanded="${ui.filters}">${icon('filter')}Filters${ui.protocol!=='all'||ui.lock!=='all'?' •':''}</button><div class="view-switch"><button class="icon-btn ${ui.view==='list'?'active':''}" data-action="view" data-view="list" aria-label="List view" aria-pressed="${ui.view==='list'}">${icon('list')}</button><button class="icon-btn ${ui.view==='grid'?'active':''}" data-action="view" data-view="grid" aria-label="Card view" aria-pressed="${ui.view==='grid'}">${icon('market')}</button></div></div></div>
 ${ui.filters?`<div class="filter-panel"><div class="field"><label for="protocol-filter">Protocol</label><select id="protocol-filter">${['all','Raydium'].map(v=>`<option value="${v}" ${ui.protocol===v?'selected':''}>${v==='all'?'All protocols':v}</option>`).join('')}</select></div><div class="field"><label for="lock-filter">Lock duration</label><select id="lock-filter"><option value="all">All durations</option><option value="short" ${ui.lock==='short'?'selected':''}>90 days or less</option><option value="permanent" ${ui.lock==='permanent'?'selected':''}>Permanent</option></select></div><button class="secondary" data-action="clear-filters">Clear filters</button></div>`:''}<div id="results"></div>`;
 renderResults();restoreFocus(focused,$('#main'));
}
function renderResults(){const focused=focusToken($('#results'));const items=filtered();$('#result-count').textContent=items.length;$('#results').innerHTML=`<div class="market-panel"><div class="market-summary"><span>${state.loading?'Loading positions…':`${items.length} ${items.length===1?'position':'positions'}`}</span><label class="sort-control">Sort by<select id="sort" aria-label="Sort positions">${[['newest','Newest listed'],['price-low','Price: low to high'],['price-high','Price: high to low']].map(([v,l])=>`<option value="${v}" ${ui.sort===v?'selected':''}>${l}</option>`).join('')}</select></label></div>${state.error?empty('Market unavailable',esc(state.error),'<button class="secondary" data-action="refresh">Try again</button>'):items.length?(ui.view==='grid'?`<div class="market-grid" style="padding:15px">${items.map(p=>card(p)).join('')}</div>`:table(items)):empty(state.loading?'Loading positions':ui.page==='saved'?'Your watchlist is empty':'No positions listed yet',state.loading?'Reading the marketplace.':ui.page==='saved'?'Save a position to follow it here.':ui.tab==='LP position'?'The first market supports Raydium Burn & Earn Fee Keys.':'Connect a wallet with a Raydium Fee Key to create the first listing.',state.loading?'':createButton(),ui.page==='saved'?'bookmark':'search')}<div class="table-bottom"><span>${state.error?'Refresh to reconnect':`Showing ${items.length} of ${state.listings.filter(p=>p.status==='active').length} positions`}</span><span>${brandLogo('SOL')}Prices in SOL</span></div></div>`;restoreFocus(focused,$('#results'));}
function table(items){return `<div class="market-table-wrap"><table class="market-table"><thead><tr><th>Position</th><th>Rights offered</th><th>Asking price</th><th class="fees-column">Verified on-chain</th><th>Lock remaining</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${items.map(p=>`<tr data-id="${esc(p.id)}" data-action="detail" tabindex="0" aria-label="View ${esc(p.base)} ${esc(p.quote)} ${esc(p.protocol)} position"><td>${pair(p)}</td><td>${tag(p)}</td><td><span class="price">${lamportsToSol(p.priceLamports)}<small>SOL</small></span><span class="sub positive">${referenceLabel(p)}</span></td><td class="fees-column">${p.verifiedSlot?`Slot ${esc(p.verifiedSlot)}`:'—'}<span class="sub">Raydium Burn & Earn</span></td><td><span class="lock">${icon('lock')}${lockText(p)}</span><span class="sub">Full Fee Key</span></td><td><div class="row-actions">${saveButton(p)}<span class="icon-btn">${icon('up')}</span></div></td></tr>`).join('')}</tbody></table></div><div class="mobile-card-list">${items.map(p=>`<div class="mobile-market-row" data-action="detail" data-id="${esc(p.id)}" tabindex="0" role="button" aria-label="View ${esc(p.base)} ${esc(p.quote)} ${esc(p.protocol)} position"><div class="mobile-row-top">${pair(p)}${saveButton(p)}</div><div class="mobile-row-bottom"><span><span class="price">${lamportsToSol(p.priceLamports)}<small>SOL</small></span><span class="sub positive">${referenceLabel(p)}</span></span>${tag(p)}<span class="lock">${icon('lock')}${lockText(p)}</span></div></div>`).join('')}</div>`;}
function card(p,mode='market'){return `<article class="position-card" role="button" data-action="detail" data-id="${esc(p.id)}" tabindex="0" aria-label="View ${esc(p.base)} ${esc(p.quote)} ${esc(p.protocol)} position"><div class="card-top">${pair(p)}${mode==='market'?saveButton(p):`<span class="type-tag">${esc(p.status||'Owned')}</span>`}</div><div class="card-middle"><div><span class="eyebrow">${mode==='owned'?'Fee rights':'Asking price'}</span><div class="price">${mode==='owned'?'Full key':lamportsToSol(p.priceLamports)}${mode==='owned'?'':'<small>SOL</small>'}</div></div>${tag(p)}</div><div class="card-bottom"><span><span class="sub">Lock remaining</span><span class="lock">${icon('lock')}${lockText(p)}</span></span><span><span class="sub">Rights included</span>Full Fee Key</span></div><div class="card-footer"><span>${mode==='owned'?'In your portfolio':'Verified Raydium Fee Key'}</span><span>View position ↗</span></div></article>`;}
function requireWallet(callback){if(state.connected){callback();return;}pendingAction=callback;walletModal();}
const tradeLabels={requested:'Waiting for seller',preparing:'Preparing the exchange',prepared:'Seller approval pending',approved:'Ready for buyer signature',submitted:'Awaiting confirmation',confirmed:'Settled on Solana',expired:'Approval expired',canceled:'Request canceled',failed:'Transaction failed'};
function tradeRows(){return state.offers.map(trade=>`<div class="activity-row"><div class="activity-icon">${icon('activity')}</div><div><p>${trade.seller===state.address?'Sale request':'Purchase request'} · ${lamportsToSol(trade.priceLamports)} SOL</p><small>${esc(tradeLabels[trade.status]||trade.status)} · ${esc(shortAddress(trade.mint))}</small></div><button class="secondary" style="margin-left:auto" data-action="trade" data-id="${esc(trade.id)}">${trade.status==='approved'&&trade.buyer===state.address?'Complete purchase':trade.seller===state.address&&['requested','prepared'].includes(trade.status)?'Review sale':'View details'}</button></div>`).join('');}
function scanSummary(){const scan=state.inventoryScan;if(scan.truncated)return scan.scannedCandidates!==null&&scan.totalCandidates!==null?`Checked ${scan.scannedCandidates} of ${scan.totalCandidates} candidate holdings. The remaining holdings have not been checked.`:'Inventory scan is incomplete. Additional Fee Keys may be held by this wallet.';return scan.rejected?`${scan.rejected} candidate ${scan.rejected===1?'holding could':'holdings could'} not be verified as supported Fee Keys.`:'';}
function renderPortfolio(){
 $('#main').innerHTML=intro('Portfolio','My positions',scanSummary()||'Your Fee Keys, active listings and purchase requests.',createButton());
 if(!state.connected){$('#main').innerHTML+=`<div class="market-panel">${empty('Your portfolio','Connect a wallet to view your Raydium Fee Keys.',`<button class="primary" data-action="wallet">${icon('wallet')}Connect wallet</button>`,'wallet')}</div>`;return;}
 $('#main').innerHTML+=`<div class="stats"><div class="stat dark"><span>Available balance</span><strong>${currency(state.balance)} <small>SOL</small></strong><p>${chainLabel()} wallet balance</p></div><div class="stat"><span>${state.inventoryScan.truncated?'Positions found':'Positions owned'}</span><strong>${state.inventoryError?'—':state.positions.length}</strong><p>Verified Raydium Burn & Earn Fee Keys</p></div><div class="stat"><span>Open requests</span><strong>${state.offers.filter(t=>['requested','prepared','approved','submitted'].includes(t.status)).length}</strong><p>Funds stay in your wallet until settlement</p></div></div><div class="section-heading"><h2>Your positions <span class="count-badge">${state.positions.length}</span></h2><button class="text-link" data-action="refresh">Refresh ${icon('refresh')}</button></div>${state.inventoryError?`<div class="market-panel">${empty('Couldn’t load your positions',esc(state.inventoryError),'<button class="secondary" data-action="refresh">Try again</button>')}</div>`:state.positions.length?`<div class="market-grid">${state.positions.map(p=>card(p,'owned')).join('')}</div>`:`<div class="market-panel">${empty(state.inventoryLoading?'Loading your Fee Keys':state.inventoryScan.truncated?'No Fee Keys in this scan':'No Fee Keys found',state.inventoryLoading?'Reading ownership and Raydium lock accounts.':scanSummary()||'Only verified Raydium Burn & Earn Fee Keys held by this wallet can be listed.','','wallet')}</div>`}${state.offers.length?`<div class="section-heading" style="margin-top:30px"><h2>Purchase requests</h2></div><div class="activity-list">${tradeRows()}</div>`:''}`;
}
function renderListings(){const own=state.listings.filter(p=>p.seller===state.address);$('#main').innerHTML=intro('Manage liquidity','My listings','Manage your Raydium Fee Key listings.',createButton());if(!state.connected){$('#main').innerHTML+=`<div class="market-panel">${empty('No listings yet','Connect a wallet to list a Fee Key.',`<button class="primary" data-action="wallet">Connect wallet</button>`,'list')}</div>`;return;}const filtered=own.filter(p=>ui.listingTab==='all'||p.status===ui.listingTab||(ui.listingTab==='active'&&p.status==='reserved'));$('#main').innerHTML+=`<div class="toolbar"><div class="tabs">${['active','canceled','all'].map(t=>`<button class="tab ${ui.listingTab===t?'active':''}" data-action="listing-tab" data-tab="${t}">${t==='all'?'All listings':t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><span class="eyebrow">${own.filter(p=>p.status==='active').length} active</span></div>${filtered.length?`<div class="market-grid">${filtered.map(p=>card(p,'listing')).join('')}</div>`:`<div class="market-panel">${empty('No listings yet','Choose a verified Fee Key and set your price.',createButton(),'list')}</div>`}${state.offers.some(t=>t.seller===state.address)?`<div class="section-heading" style="margin-top:30px"><h2>Purchase requests</h2></div><div class="activity-list">${tradeRows()}</div>`:''}`;}
function renderActivity(){$('#main').innerHTML=intro('Account history','Activity','Authenticated listings and confirmed transactions.')+(state.activity.length?`<div class="activity-list">${state.activity.map(a=>`<div class="activity-row"><div class="activity-icon">${icon(a.kind||'activity')}</div><div><p>${esc(a.title||a.type)}</p><small>${esc(a.description||'')}${a.signature?` · <a href="${explorer('tx',a.signature)}" target="_blank" rel="noopener noreferrer">View transaction ↗</a>`:''}</small></div><div class="activity-amount">${a.amount===null||a.amount===undefined?'':`${a.amount>0?'+':''}${currency(a.amount)} SOL`}<small>${new Date(a.at||a.createdAt).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</small></div></div>`).join('')}</div>`:`<div class="market-panel">${empty('No activity yet','Listings and settlements will appear here.',`<button class="primary" data-action="browse">Explore marketplace ${icon('arrow')}</button>`,'activity')}</div>`);}
function navigate(page){ui.page=page;close();$('#sidebar').classList.remove('mobile-open');ui.query='';ui.tab='all';ui.protocol='all';ui.lock='all';render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});animateElement($('#main'),[{opacity:.35,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:280});}
function openDialog(content,{drawer=false,wide=false,kind='default'}={}){
 clearTimeout(dismissTimer);
 const root=$('#overlay-root'),previous=root.querySelector('[role="dialog"]');
 if(!previous)lastFocus=document.activeElement;
 const focused=focusToken(previous);
 const chrome=`<div class="dialog-chrome"><a class="dialog-brand" href="../index.html" aria-label="Sona home"><img class="symbol" src="${asset('Ra1fh0MoVH2kB555Dxfse0f7d8E.png')}" alt=""><img class="wordmark" src="${asset('sona-wordmark.svg')}" alt="Sona"></a><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>`;
 const sameSurface=previous?.classList.contains(`dialog-${kind}`)&&previous.classList.contains(drawer?'drawer':'modal');
 if(sameSurface){
  const scroll=previous.scrollTop;
  previous.innerHTML=chrome+content;
  previous.closest('.overlay').classList.remove('is-closing');
  previous.scrollTop=scroll;
  restoreFocus(focused,previous);
  if(!previous.contains(document.activeElement))previous.focus({preventScroll:true});
  [...previous.children].slice(1).forEach(el=>animateElement(el,[{opacity:.45,transform:'translateY(3px)'},{opacity:1,transform:'translateY(0)'}],{duration:180}));
 }else{
  root.innerHTML=`<div class="overlay ${drawer?'':'center'}" data-dismiss="true"><section class="${drawer?'drawer':`modal ${wide?'wide':''}`} dialog-${kind}" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1">${chrome}${content}</section></div>`;
  requestAnimationFrame(()=>root.querySelector('[role="dialog"]')?.focus());
 }
 document.body.classList.add('no-scroll');$('.app-shell').inert=true;$('#sidebar').inert=true;
}
function close(){if(dismissTimer)clearTimeout(dismissTimer);$('#overlay-root').innerHTML='';document.body.classList.remove('no-scroll');$('.app-shell').inert=false;$('#sidebar').inert=false;if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});lastFocus=null;currentPosition=null;pendingAction=null;}
function dismissDialog(){const overlay=$('#overlay-root .overlay');if(!overlay||!motionAllowed()){close();return;}if(overlay.classList.contains('is-closing'))return;overlay.classList.add('is-closing');dismissTimer=setTimeout(close,170);}
const closeButton=()=>'';
const findPosition=id=>state.listings.find(p=>p.id===id)||state.positions.find(p=>p.id===id);
function showDetail(id,tab='overview'){
 const p=findPosition(id);if(!p){toast('This position is no longer available.');return;}currentPosition=id;ui.detailTab=tab;
 const owned=state.positions.some(pos=>pos.mint===p.mint);const ownListing=p.seller===state.address&&p.status;const activeListing=state.listings.find(l=>l.mint===p.mint&&['active','reserved'].includes(l.status));
 let body='';
 if(tab==='overview')body=`<div class="detail-metrics"><div class="detail-metric"><span>Liquidity lock</span><strong>Permanent</strong><small>Underlying principal stays locked</small></div><div class="detail-metric"><span>Rights included</span><strong>Full Fee Key</strong><small>Attached fee-collection rights</small></div><div class="detail-metric"><span>On-chain verification</span><strong>${esc(p.verifiedSlot||'—')}</strong><small>Solana slot</small></div><div class="detail-metric"><span>Market type</span><strong>Raydium</strong><small>Burn & Earn</small></div></div><div class="rights-note">${icon('lock')}<div><h3>Fee rights only</h3><p>The Fee Key NFT transfers to the buyer. The underlying locked liquidity cannot be withdrawn through this purchase.</p></div></div><div class="detail-ownership"><span>Fee Key</span><a href="${explorer('address',p.mint)}" target="_blank" rel="noopener noreferrer">${esc(shortAddress(p.mint))} ↗</a></div><div class="detail-ownership"><span>Listed by</span><span>${ownListing?'You':esc(shortAddress(p.seller||p.owner))}</span></div>`;
 else if(tab==='terms')body=`<ul class="risk-list"><li><b>Rights included</b>Ownership of one verified Raydium Burn & Earn Fee Key, with its attached fee-collection rights. No principal redemption.</li><li><b>Both wallets approve</b>The seller reviews the buyer’s request. The buyer then signs the same transaction before its blockhash expires.</li><li><b>Atomic exchange</b>The Fee Key and payment transfer in one Solana transaction. If any instruction fails, neither transfer completes; network fees may still apply.</li><li><b>Network costs</b>The buyer pays Solana transaction fees and any required token-account rent, in addition to the asking price.</li><li><b>Fees and market risk</b>Future fee income depends on pool activity. No yield or market value is guaranteed.</li><li><b>Public settlement</b>Wallets, price and transfers are visible on Solana.</li></ul>`;
 else body=`<div class="detail-description">${ownListing?'You created this listing.':`Listed by ${esc(shortAddress(p.seller||p.owner))}.`}</div><div class="activity-list"><div class="activity-row"><div class="activity-icon">${icon('list')}</div><div><p>${owned?'Held by your wallet':'Fee Key listing'}</p><small>${p.createdAt?new Date(p.createdAt).toLocaleString():'Verified against Raydium lock state'}</small></div></div></div>`;
 let actions=ownListing?(p.status==='active'?`<button class="primary" data-action="edit-listing" data-id="${esc(p.id)}">Edit asking price</button><button class="secondary" data-action="copy-link" data-id="${esc(p.id)}">${icon('copy')}Copy listing link</button><button class="secondary" data-action="cancel-listing" data-id="${esc(p.id)}">Cancel listing</button>`:`<p class="inline-note">Listing ${esc(p.status)}.</p>`):owned?(activeListing?`<button class="primary" data-action="detail" data-id="${esc(activeListing.id)}">Manage listing</button>`:`<button class="primary" data-action="create" data-id="${esc(p.id)}">List this position</button>`):p.status==='active'?`<button class="primary" data-action="buy" data-id="${esc(p.id)}">Buy fee rights</button><button class="secondary" data-action="copy-link" data-id="${esc(p.id)}">${icon('copy')}Copy listing link</button>`:'<p class="inline-note">This position is no longer available.</p>';
 openDialog(`<div class="detail-pair">${tokens(p)}<div><h2 id="dialog-title">${esc(p.base)} <span class="pair-divider">/</span> ${esc(p.quote)}</h2><p class="detail-protocol">${brandLogo(p.protocol,'protocol-logo')}${esc(p.protocol)}<span>·</span>${ownListing?'Your listing':owned?'Your position':'Fee Key'}</p></div>${!owned?saveButton(p):''}</div><div class="price-panel"><span class="eyebrow">${owned&&!ownListing?'Rights included':'Asking price'}</span>${tag(p)}<div class="detail-price">${owned&&!ownListing?'Full Fee Key':`${lamportsToSol(p.priceLamports)} <small>${brandLogo('SOL')}SOL</small>`}</div><span class="discount">${referenceLabel(p)}</span></div><div class="detail-tabs">${[['overview','Overview'],['terms','Terms & risks'],['activity','Activity']].map(([v,l])=>`<button class="${tab===v?'active':''}" data-action="detail-tab" data-tab="${v}" data-id="${esc(p.id)}">${l}</button>`).join('')}</div>${body}<div class="detail-actions">${actions}</div><div class="dialog-foot"><span>${chainLabel()}</span><button class="plain" data-action="connection-info">Connection status ${icon('info')}</button></div>`,{drawer:true,kind:'position'});
}
function walletModal(){
 if(state.connected){openDialog(`<div class="modal-head"><h2 id="dialog-title">Your wallet</h2><p>${esc(state.address)}</p></div><div class="transaction-total"><span>Available balance</span><strong>${currency(state.balance)} <small>${brandLogo('SOL')}SOL</small></strong></div><div class="summary-rows"><div class="summary-row"><span>Fee Keys</span><b>${state.positions.length}</b></div><div class="summary-row"><span>Open requests</span><b>${state.offers.filter(t=>['requested','prepared','approved'].includes(t.status)).length}</b></div><div class="summary-row"><span>Network</span><b>${chainLabel()}</b></div></div><div class="modal-actions"><button class="secondary" data-action="authenticate">${sessionToken?'Refresh wallet':'Verify account'}</button><button class="primary" data-action="disconnect">Disconnect</button></div>`,{kind:'account'});return;}
 const installed=wallet.list();const options=[...['Phantom','Solflare','Backpack'].map(name=>({name,match:installed.find(item=>item.name.toLowerCase()===name.toLowerCase())})),...installed.filter(item=>!['phantom','solflare','backpack'].includes(item.name.toLowerCase())).map(match=>({name:match.name,match}))];
 openDialog(`<div class="modal-head"><h2 id="dialog-title">Connect a wallet</h2><p>Choose the wallet that holds your Raydium Fee Keys.</p></div><div class="wallet-list">${options.map(({name,match})=>`<button class="wallet-row" ${match?`data-action="connect" data-wallet="${esc(match.id)}"`:'disabled'} aria-label="${esc(name)}${match?'':', not detected'}">${brandLogo(name,'wallet-logo')}<span class="wallet-name">${esc(name)}</span><span class="wallet-availability">${match?'Connect':'Not detected'}</span></button>`).join('')}</div><p class="connection-note">A message signature verifies your wallet. No funds move when you connect.${installed.length?'':' Open this site in a browser with your wallet extension installed.'}</p>`,{kind:'wallet'});
}
function buyReview(id){requireWallet(()=>{const p=findPosition(id);if(!p||p.status!=='active'||p.seller===state.address)return toast('This position is not available to buy.');currentPosition=id;openDialog(`<div class="modal-head"><h2 id="dialog-title">Review purchase</h2><p>Send the seller a request at the listed price.</p></div><div class="position-ticket">${pair(p)}${tag(p)}</div><div class="transaction-total"><span>Asking price</span><strong>${lamportsToSol(p.priceLamports)} <small>${brandLogo('SOL')}SOL</small></strong></div><div class="summary-rows"><div class="summary-row"><span>Rights included</span><b>Full Fee Key</b></div><div class="summary-row"><span>Liquidity lock</span><b>Permanent</b></div><div class="summary-row"><span>Network fees & account rent</span><b>Paid by buyer</b></div><div class="summary-row"><span>Your balance</span><b>${currency(state.balance)} SOL</b></div></div><label class="check-label"><input type="checkbox" id="purchase-consent">I understand that this transfers fee rights, not the underlying principal.</label><div class="modal-actions"><button class="secondary" data-action="detail" data-id="${esc(p.id)}">Back</button><button class="primary" id="confirm-buy" data-action="confirm-buy" data-id="${esc(p.id)}" disabled>Request purchase</button></div><p class="connection-note">No funds are reserved. After the seller approves, review and sign the exchange in your wallet.</p>`,{kind:'purchase'});});}
async function buy(id){if(!$('#purchase-consent')?.checked)return;const p=findPosition(id);if(!p||p.status!=='active'||p.seller===state.address)return;const {trade}=await api(`/api/listings/${encodeURIComponent(id)}/request`,{method:'POST',body:{},authenticated:true});await refreshData();await showTrade(trade.id);}
async function showTrade(id){const {trade}=await api(`/api/trades/${encodeURIComponent(id)}`,{authenticated:true});reviewedTrades.set(id,{seller:trade.seller,buyer:trade.buyer,mint:trade.mint,priceLamports:trade.priceLamports});const isSeller=trade.seller===state.address;const p=state.listings.find(p=>p.id===trade.listingId);let action='';if(isSeller&&['requested','prepared'].includes(trade.status))action=`<button class="primary" data-action="approve-trade" data-id="${esc(id)}">Review & sign sale</button>`;if(!isSeller&&trade.status==='approved')action=`<button class="primary" data-action="settle-trade" data-id="${esc(id)}">Review & complete purchase</button>`;
 openDialog(`<div class="modal-head"><h2 id="dialog-title">${trade.status==='confirmed'?'Exchange complete':isSeller?'Review sale':'Your purchase request'}</h2><p>${esc(tradeLabels[trade.status]||trade.status)}</p></div>${p?`<div class="position-ticket">${pair(p)}${tag(p)}</div>`:''}<div class="transaction-total"><span>Sale price</span><strong>${lamportsToSol(trade.priceLamports)} <small>${brandLogo('SOL')}SOL</small></strong></div><div class="summary-rows"><div class="summary-row"><span>Fee Key</span><b>${esc(shortAddress(trade.mint))}</b></div><div class="summary-row"><span>Seller</span><b>${esc(shortAddress(trade.seller))}</b></div><div class="summary-row"><span>Buyer</span><b>${esc(shortAddress(trade.buyer))}</b></div><div class="summary-row"><span>Settlement</span><b>Atomic exchange on Solana</b></div></div>${trade.signature?`<p class="connection-note"><a href="${explorer('tx',trade.signature)}" target="_blank" rel="noopener noreferrer">View transaction on Solana ↗</a></p>`:`<p class="inline-note">${trade.status==='approved'?'Seller approval is time-limited. Both transfers complete together when the buyer signs and the network confirms.':isSeller?'Signing approves this exact buyer and price for a short time. Keep this window available while the buyer completes the exchange.':'The seller must approve this request before your wallet signs the exchange. Funds stay in your wallet until then.'}</p>`}<div class="modal-actions">${['requested','prepared'].includes(trade.status)?`<button class="secondary" data-action="cancel-trade" data-id="${esc(id)}">Cancel request</button>`:`<button class="secondary" data-action="trade" data-id="${esc(id)}">Refresh status</button>`}${action||'<button class="primary" data-action="nav" data-page="portfolio">My positions</button>'}</div>`,{kind:'purchase'});
}
function checkedSettlement(trade,settlement){const reviewed=reviewedTrades.get(trade.id);if(!reviewed||['seller','buyer','mint','priceLamports'].some(key=>reviewed[key]!==trade[key]))throw new Error('Purchase terms changed. Reopen and review the request.');if(!settlement)throw new Error('Settlement is not ready. Refresh the request.');for(const key of ['seller','buyer','mint','priceLamports'])if(settlement[key]!==trade[key])throw new Error('Settlement terms changed. Review a new request.');assertSettlementTransaction(settlement.transactionBase64,{...settlement,seller:trade.seller,buyer:trade.buyer,mint:trade.mint,priceLamports:trade.priceLamports});return settlement.transactionBase64;}
async function approveTrade(id){let result=await api(`/api/trades/${encodeURIComponent(id)}`,{authenticated:true});if(result.trade.status==='requested')result=await api(`/api/trades/${encodeURIComponent(id)}/prepare`,{method:'POST',body:{},authenticated:true});if(result.trade.status!=='prepared')throw new Error('This request is not ready for seller approval. Refresh its status.');const {trade,settlement}=result;if(trade.seller!==state.address)throw new Error('Connect the seller wallet.');const transactionBase64=await wallet.signTransaction(checkedSettlement(trade,settlement));await api(`/api/trades/${encodeURIComponent(id)}/approve`,{method:'POST',body:{transactionBase64},authenticated:true});await refreshData();await showTrade(id);}
async function settleTrade(id){const {trade,settlement}=await api(`/api/trades/${encodeURIComponent(id)}`,{authenticated:true});if(trade.buyer!==state.address||trade.status!=='approved')throw new Error('This request is not ready for your signature.');const transactionBase64=await wallet.signTransaction(checkedSettlement(trade,settlement));await api(`/api/trades/${encodeURIComponent(id)}/submit`,{method:'POST',body:{transactionBase64},authenticated:true});await refreshData();await showTrade(id);}
function startWizard(positionId){requireWallet(()=>{if(state.inventoryLoading)return toast('Your Fee Keys are still loading. Try again shortly.');if(state.inventoryError)return toast(state.inventoryError);const eligible=state.positions.filter(p=>!state.listings.some(l=>l.mint===p.mint&&['active','reserved'].includes(l.status)));if(!eligible.length){navigate('portfolio');toast(state.positions.length?'All verified Fee Keys in this scan are already listed.':state.inventoryScan.truncated?'No eligible Fee Keys were found in the inspected holdings. The wallet scan is incomplete.':'No eligible Raydium Fee Keys were found in this wallet.');return;}wizard={step:1,id:eligible.some(p=>p.id===positionId)?positionId:eligible[0].id,price:'',expiresInDays:7};showWizard();});}
function showWizard(){const p=state.positions.find(p=>p.id===wizard.id);if(!p)return;const eligible=state.positions.filter(p=>!state.listings.some(l=>l.mint===p.mint&&['active','reserved'].includes(l.status)));let content='';if(wizard.step===1)content=`<p class="modal-intro">Select a verified Fee Key from your wallet.</p>${eligible.map(pos=>`<button class="position-choice ${pos.id===wizard.id?'selected':''}" data-action="select-position" data-id="${esc(pos.id)}" aria-pressed="${pos.id===wizard.id}">${pair(pos)}<span>${tag(pos)}</span><span class="radio-dot"></span></button>`).join('')}<p class="inline-note">The Fee Key stays in your wallet until you approve a buyer and the exchange settles.</p>`;
 if(wizard.step===2)content=`${pair(p)}<div class="form-grid"><div class="field"><label for="listing-price">Asking price</label><div class="price-input"><input id="listing-price" type="number" min="0.000000001" max="1000000" step="0.000000001" value="${esc(wizard.price)}" placeholder="0.00" required><span>${brandLogo('SOL')}SOL</span></div><small>Set the price for the full Fee Key.</small><div class="field-error" id="price-error" role="alert"></div></div><div class="field"><label>Listing duration</label><div class="visibility-options">${[7,30].map(days=>`<button class="visibility-option ${wizard.expiresInDays===days?'selected':''}" data-action="duration" data-value="${days}" aria-pressed="${wizard.expiresInDays===days}">${icon('list')}<span>${days} days</span><small>Cancel earlier from My listings.</small></button>`).join('')}</div></div><div class="notice">Listing is free. You approve each buyer; no escrow deposit is needed.</div></div>`;
 if(wizard.step===3)content=`${pair(p)}<div class="summary-rows"><div class="summary-row"><span>Rights offered</span><b>Full Fee Key</b></div><div class="summary-row"><span>Liquidity lock</span><b>Permanent</b></div><div class="summary-row"><span>Expires after</span><b>${wizard.expiresInDays} days</b></div><div class="summary-row"><span>Network</span><b>${chainLabel()}</b></div><div class="summary-row total"><span>Asking price</span><b>${lamportsToSol(solToLamports(wizard.price))} SOL</b></div></div><label class="check-label"><input type="checkbox" id="listing-consent">I’ve reviewed the price, fee rights and listing duration.</label>`;
 openDialog(`<div class="modal-head"><h2 id="dialog-title">List a position</h2><p>Choose your Fee Key, set the terms, and review.</p></div><div class="steps">${['Position','Your terms','Review'].map((label,i)=>`${i?'<span class="step-line"></span>':''}<span class="step ${wizard.step===i+1?'active':''}"><b>${i+1}</b>${label}</span>`).join('')}</div>${content}<div class="modal-actions"><button class="secondary" data-action="${wizard.step===1?'close':'wizard-back'}">${wizard.step===1?'Cancel':'Back'}</button><button class="primary" data-action="${wizard.step===3?'publish-listing':'wizard-next'}" ${wizard.step===3?'id="publish-listing" disabled':''}>${wizard.step===3?'Create listing':'Continue'} ${icon('arrow')}</button></div>`,{wide:true,kind:'listing'});}
async function publishListing(){if(!$('#listing-consent')?.checked||!wizard||!state.connected)return;const p=state.positions.find(p=>p.id===wizard.id);if(!p)return;const {listing}=await api('/api/listings',{method:'POST',body:{mint:p.mint,priceLamports:solToLamports(wizard.price),expiresInDays:wizard.expiresInDays},authenticated:true});wizard=null;await refreshData();showDetail(listing.id);toast('Your Fee Key is listed.');}
function editListing(id){const p=findPosition(id);if(p?.seller!==state.address||p.status!=='active')return;openDialog(`<h2 id="dialog-title">Edit asking price</h2><p>${esc(p.base)} / ${esc(p.quote)} · Fee rights</p><form id="edit-form" data-id="${esc(p.id)}" class="form-grid"><div class="field"><label for="edit-price">Asking price in SOL</label><input id="edit-price" type="number" min="0.000000001" max="1000000" step="0.000000001" value="${solDecimal(p.priceLamports)}" required></div><button class="primary" type="submit">Save price ${icon('check')}</button></form>`);}
function cancelListing(id){const p=findPosition(id);if(p?.seller!==state.address||p.status!=='active')return;openDialog(`<h2 id="dialog-title">Cancel this listing?</h2><p>Your Fee Key stays in your wallet. The listing will no longer accept new requests. An already signed approval may remain valid until its blockhash expires.</p><div class="modal-actions"><button class="secondary" data-action="detail" data-id="${esc(id)}">Keep listing</button><button class="primary" data-action="confirm-cancel" data-id="${esc(id)}">Cancel listing</button></div>`);}
function guide(){openDialog(`<div class="modal-head"><h2 id="dialog-title">How positions work</h2><p>Trade Raydium Fee Keys while the liquidity stays locked.</p></div>${[['Verify the Fee Key','Sona checks the Raydium Burn & Earn lock state and the NFT held by the seller.'],['List and request','A wallet signature verifies your account. Listings are free, and buyers request a purchase at the asking price.'],['Approve and settle','The seller signs first. The buyer signs the same transaction before it expires. The Fee Key and SOL exchange atomically.']].map(([h,p],i)=>`<div class="guide-step"><span>${i+1}</span><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}<p class="connection-note">The buyer pays network fees and any new token-account rent. Settlement is public on Solana.</p><div class="modal-actions"><button class="primary" data-action="close">Back to marketplace</button></div>`,{wide:true,kind:'guide'});}
function connectionInfo(){openDialog(`<div class="modal-head"><h2 id="dialog-title">Connection status</h2><p>${state.error?'The marketplace service is unavailable.':`${chainLabel()} · Raydium Burn & Earn`}</p></div><div class="guide-step"><div><h3>Verified wallet ownership</h3><p>${state.connected?`${esc(shortAddress(state.address))} is connected. ${sessionToken?'Your account signature is verified.':'Verify your account before managing listings.'}`:'Connect a supported Solana wallet to load your Fee Keys.'}</p></div></div><div class="guide-step"><div><h3>Atomic exchange</h3><p>Listings and requests are hosted by Sona. Both wallets sign a single transaction to exchange a verified Fee Key for SOL. No Sona custody or custom escrow program.</p><p class="connection-note"><a href="../technical/">Implementation details</a></p></div></div><div class="modal-actions"><button class="primary" data-action="refresh">Refresh connection</button></div>`,{kind:'about'});}
document.addEventListener('click',async event=>{
 if(event.target.dataset.dismiss==='true'){dismissDialog();return;}
 const target=event.target.closest('[data-action]');if(!target)return;const {action,id}=target.dataset;
 if(action==='menu'){$('#sidebar').classList.toggle('mobile-open');return;}
 if(action==='nav')navigate(target.dataset.page);
 if(action==='browse')navigate('market');
 if(action==='close')dismissDialog();
 if(action==='wallet')walletModal();
 if(action==='connect')await runAction(target,async()=>{const next=pendingAction;await wallet.connect(target.dataset.wallet);close();await ensureSession();await refreshData();toast('Wallet connected');if(next)next();});
 if(action==='authenticate')await runAction(target,async()=>{await ensureSession();await refreshData();walletModal();});
 if(action==='disconnect')await runAction(target,async()=>{if(sessionToken)await api('/api/auth/logout',{method:'POST',body:{}}).catch(()=>{});await wallet.disconnect();close();render();toast('Wallet disconnected');});
 if(action==='connection-info')connectionInfo();
 if(action==='refresh')await runAction(target,async()=>{await refreshData();if($('#overlay-root .dialog-about'))connectionInfo();});
 if(action==='guide')guide();
 if(action==='tab'){ui.tab=target.dataset.tab;document.querySelectorAll('[data-action="tab"]').forEach(button=>{const active=button.dataset.tab===ui.tab;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});renderResults();animateElement($('#results'),[{opacity:.55,transform:'translateY(3px)'},{opacity:1,transform:'translateY(0)'}]);}
 if(action==='filters'){ui.filters=!ui.filters;renderMarket();}
 if(action==='view'){ui.view=target.dataset.view;document.querySelectorAll('[data-action="view"]').forEach(button=>{const active=button.dataset.view===ui.view;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});renderResults();animateElement($('#results'),[{opacity:.4,transform:'translateY(4px)'},{opacity:1,transform:'translateY(0)'}]);}
 if(action==='clear-filters'){ui.query='';ui.protocol='all';ui.lock='all';ui.tab='all';renderMarket();}
 if(action==='listing-tab'){ui.listingTab=target.dataset.tab;renderListings();}
 if(action==='save'){event.stopPropagation();const wasSaved=state.saved.includes(id);state.saved=wasSaved?state.saved.filter(v=>v!==id):[...state.saved,id];persist();nav();if(ui.page==='market'||ui.page==='saved')renderResults();if(currentPosition===id)showDetail(id,ui.detailTab);toast(wasSaved?'Removed from watchlist':'Saved to watchlist');}
 if(action==='detail')showDetail(id);
 if(action==='detail-tab')showDetail(id,target.dataset.tab);
 if(action==='buy')buyReview(id);
 if(action==='confirm-buy')await runAction(target,()=>buy(id));
 if(action==='trade')await runAction(target,()=>showTrade(id));
 if(action==='approve-trade')await runAction(target,()=>approveTrade(id));
 if(action==='settle-trade')await runAction(target,()=>settleTrade(id));
 if(action==='cancel-trade')await runAction(target,async()=>{await api(`/api/trades/${encodeURIComponent(id)}/cancel`,{method:'POST',body:{},authenticated:true});await refreshData();await showTrade(id);});
 if(action==='create')startWizard(id);
 if(action==='select-position'){wizard.id=id;wizard.price='';showWizard();}
 if(action==='duration'){wizard.price=$('#listing-price').value;wizard.expiresInDays=Number(target.dataset.value);showWizard();}
 if(action==='wizard-back'){if(wizard.step===2)wizard.price=$('#listing-price').value;wizard.step--;showWizard();}
 if(action==='wizard-next'){if(wizard.step===2){try{const value=$('#listing-price').value;solToLamports(value);wizard.price=value;}catch(error){$('#price-error').textContent=error.message;$('#listing-price').focus();return;}}wizard.step++;showWizard();}
 if(action==='publish-listing')await runAction(target,publishListing);
 if(action==='edit-listing')requireWallet(()=>editListing(id));
 if(action==='cancel-listing')requireWallet(()=>cancelListing(id));
 if(action==='confirm-cancel')await runAction(target,async()=>{await api(`/api/listings/${encodeURIComponent(id)}`,{method:'DELETE',authenticated:true});close();await refreshData();toast('Listing canceled. Your Fee Key stays in your wallet.');});
 if(action==='copy-link'){const link=`${location.origin}${location.pathname}#deal/${encodeURIComponent(id)}`;try{await navigator.clipboard.writeText(link);toast('Listing link copied.');}catch{openDialog(`<h2 id="dialog-title">Listing link</h2><p>Copy this URL to share the listing.</p><div class="field" style="margin-top:20px"><label for="manual-link">Listing link</label><input id="manual-link" readonly value="${esc(link)}"></div><div class="modal-actions"><button class="primary" data-action="close">Done</button></div>`);}}
});
document.addEventListener('input',event=>{if(event.target.id==='search'){ui.query=event.target.value;renderResults();}if(event.target.id==='listing-price')$('#price-error').textContent='';if(event.target.id==='purchase-consent')$('#confirm-buy').disabled=!event.target.checked;if(event.target.id==='listing-consent')$('#publish-listing').disabled=!event.target.checked;});
document.addEventListener('change',event=>{if(event.target.id==='protocol-filter'){ui.protocol=event.target.value;renderResults();}if(event.target.id==='lock-filter'){ui.lock=event.target.value;renderResults();}if(event.target.id==='sort'){ui.sort=event.target.value;renderResults();}});
document.addEventListener('submit',async event=>{if(event.target.id!=='edit-form')return;event.preventDefault();const form=event.target;const price=$('#edit-price').value;await runAction(form.querySelector('button[type="submit"]'),async()=>{await api(`/api/listings/${encodeURIComponent(form.dataset.id)}`,{method:'PATCH',body:{priceLamports:solToLamports(price)},authenticated:true});await refreshData();showDetail(form.dataset.id);toast('Asking price updated.');});});
document.addEventListener('keydown',event=>{
 if(event.key==='/'&&!event.ctrlKey&&!event.metaKey&&!event.altKey&&!event.target.matches('input,textarea,select,[contenteditable="true"]')){const search=$('#search');if(search&&!$('#overlay-root [role="dialog"]')){event.preventDefault();search.focus();}}
 const modal=$('#overlay-root [role="dialog"]');if(event.key==='Escape'){if(modal)dismissDialog();else $('#sidebar').classList.remove('mobile-open');}
 if(modal&&event.key==='Tab'){const focusable=[...modal.querySelectorAll('button,a[href],input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled&&el.offsetParent!==null);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===modal)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===modal)){event.preventDefault();first?.focus();}}
 if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-action="detail"]:not(button)')){event.preventDefault();showDetail(event.target.dataset.id);}
});
function hashDeal(){const match=location.hash.match(/^#deal\/([a-zA-Z0-9-]+)$/);if(!match)return;const p=findPosition(match[1]);if(!p){toast('This listing is no longer available.');return;}showDetail(p.id);}
window.addEventListener('hashchange',hashDeal);
window.addEventListener('storage',event=>{if(event.key!==KEY)return;try{const saved=JSON.parse(event.newValue);if(Array.isArray(saved)){state.saved=saved.filter(id=>typeof id==='string');render();}}catch{}});
document.addEventListener('click',event=>{if($('#sidebar').classList.contains('mobile-open')&&!event.target.closest('#sidebar')&&!event.target.closest('[data-action="menu"]'))$('#sidebar').classList.remove('mobile-open');});
render();mountIcons();refreshData().then(hashDeal);
setInterval(()=>{if(!document.hidden)refreshData();},15000);
